UPDATE HDOC_MARKET_AUTH
SET USERID = #{userid}, MARKET = #{market}, TYPE = #{type}, BU = #{bu},
    UPDATE_DATETIME = NOW(), UPDATE_USER = #{updateUser}, UPDATE_PROCESS = #{updateProcess}
WHERE USERID = #{userid} AND MARKET = #{market} AND TYPE = #{type} AND BU = #{bu}

UPDATE HDOC_FUNCTION_AUTH
SET FUNCTION = #{function}, USERID = #{userid},
    UPDATE_DATETIME = NOW(), UPDATE_USER = #{updateUser}, UPDATE_PROCESS = #{updateProcess}
WHERE FUNCTION = #{function} AND USERID = #{userid}
